def metric(data: pd.DataFrame) -> float:
    import numpy as np

    matches = 0
    total = 0
    for _, row in data.iterrows():
        a = row['option_a_ratings']
        b = row['option_b_ratings']
        resp = row['response']

        ttb_winner = -1
        for j in range(5):
            if a[j] > b[j]:
                ttb_winner = 0
                break
            elif b[j] > a[j]:
                ttb_winner = 1
                break

        if ttb_winner != -1:
            if resp == ttb_winner:
                matches += 1
            total += 1

    return float(matches / total) if total > 0 else 0.5

